/* 保养档案同源投影，所有数据从保养API授权读取，不创建第二套业务存储。 */
(function(root){async function read(api,equipmentId){const config=await api.request('GET','/maintenance/config');const all=async kind=>{const result=[];for(let page=1;;page++){const response=await api.request('GET','/maintenance/'+kind+'?'+new URLSearchParams({equipmentId,page,pageSize:50}));result.push(...response.items);if(result.length>=response.total)return result;}};const [plans,tasks]=await Promise.all([all('plans'),all('tasks')]);const person=id=>config.followupPeople.find(p=>p.id===id)?.name||config.people.find(p=>p.id===id)?.name||id||'—',state=id=>config.taskStates.find(s=>s.id===id)?.name||({draft:'草稿',pending_review:'待审核',published:'已发布',paused:'已暂停',terminated:'已终止'})[id]||id;const records=[],history=[];
for(const p of plans)records.push({id:p.id,equipmentId,name:p.name,status:state(p.status),content:'计划V'+p.planVersion+(p.activeVersion?' / 有效V'+p.activeVersion:''),frequency:'每'+p.interval+({day:'日',week:'周',month:'月'})[p.unit],assignee:person(p.primaryPersonId),dueAt:p.nextWindow,evidence:p.code,source:'保养计划',revision:p.revision,updatedAt:p.audit.at(-1)?.at||p.approvedAt||'—',target:'maintenance-plan',query:{id:p.id,equipment:equipmentId}});
for(const t of tasks){const query={id:t.id,equipment:equipmentId},base={equipmentId,target:'maintenance-task',query,revision:t.revision,assignee:person(t.primaryPersonId),frequency:t.windowStart+' 至 '+t.windowEnd,dueAt:t.windowEnd,updatedAt:t.audit.at(-1)?.at||t.startedAt||'—'};records.push({...base,id:t.id,name:t.name,status:state(t.status),content:'发布V'+t.planVersion+' / 执行V'+t.executionVersion,evidence:t.code,source:'保养任务'});const submissions=t.submissions?.length?t.submissions:t.submission?[t.submission]:[];for(const s of submissions)records.push({...base,id:'SUB-'+t.id+'-V'+s.executionVersion,name:'保养执行提交 V'+s.executionVersion,status:'已提交',content:s.trial,evidence:s.results.map(r=>r.evidence).filter(Boolean).join('；'),source:'保养执行',updatedAt:s.submittedAt});for(const a of t.acceptances||[])records.push({...base,id:a.id,name:'独立验收 V'+a.executionVersion,status:a.decision==='passed'?'通过':'退回',content:a.reason,evidence:[a.evidence,a.residualReview].filter(Boolean).join('；'),assignee:person(a.reviewerId),source:'保养验收',updatedAt:a.reviewedAt});for(const r of t.terminationRequests||[])records.push({...base,id:r.id,name:'终止申请 / 审核 V'+r.executionVersion,status:({pending_review:'待审核',approved:'批准终止',rejected:'已驳回'})[r.status],content:r.residualRisk+' / '+r.controlMeasures,evidence:r.followup+'；责任人 '+person(r.followupOwnerId)+'；期限 '+r.followupDueAt,assignee:person(r.requestedBy),source:'保养终止审核',updatedAt:r.reviewedAt||r.requestedAt});for(const a of t.audit)history.push({...base,id:'PM-AUD-'+t.id+'-'+a.action+'-'+a.at,action:a.action,name:'保养：'+(config.taskActionLabels[a.action]||a.action),content:(a.before?.status||'生成')+' → '+(a.after?.status||t.status),evidence:a.reason,source:'保养操作审计',updatedAt:a.at,eventAt:a.at});}
return {records,history,taskCount:tasks.length,columns:[['name','计划 / 任务 / 记录'],['source','业务类型'],['status','状态 / 决定'],['content','版本 / 结论'],['frequency','周期 / 窗口'],['assignee','主责 / 审核人'],['dueAt','到期日'],['evidence','证据 / 后续安排']]};}
const api={read};if(typeof module==='object'&&module.exports)module.exports=api;else root.EamMaintenanceArchive=api;})(typeof window!=='undefined'?window:globalThis);
